// Domyslna metoda HttpURLConnection to GET - nie trzeba jej jawnie
// ustawiac, ale robimy to dla czytelnosci.

HttpURLConnection connection = (HttpURLConnection) url.openConnection();
connection.setRequestMethod("GET");

int code = connection.getResponseCode();
System.out.println("Kod: " + code + " (" + connection.getResponseMessage() + ")");

String body = readBody(connection);
connection.disconnect();

// Aby wyslac dane w zadaniu (np. POST/PUT), trzeba:
// 1) setRequestMethod("POST")
// 2) setDoOutput(true) - domyslnie false, bo GET nie wysyla ciala
// 3) zapisac bajty do getOutputStream()
// 4) DOPIERO teraz odczytac odpowiedz - to wyzwala faktyczne wyslanie

HttpURLConnection connection = (HttpURLConnection) url.openConnection();
connection.setRequestMethod("POST");
connection.setDoOutput(true);
connection.setRequestProperty("Content-Type", "text/plain; charset=UTF-8");

byte[] payload = "Pozdrowienia!".getBytes(StandardCharsets.UTF_8);
try (OutputStream out = connection.getOutputStream()) {
    out.write(payload);
}

int code = connection.getResponseCode(); // 201 Created

private static String readBody(HttpURLConnection connection) throws Exception {
    var stream = connection.getResponseCode() >= 400
            ? connection.getErrorStream()
            : connection.getInputStream();

    if (stream == null) {
        return "";
    }

    StringBuilder sb = new StringBuilder();
    try (BufferedReader reader = new BufferedReader(
            new InputStreamReader(stream, StandardCharsets.UTF_8))) {
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
    }
    return sb.toString();
}
